data class Mutation(
    val addTodo: Todo? = null,
) {
    fun toJson(): Map<String, Any?> = buildMap {
        if (addTodo != null) put("addTodo", addTodo.toJson())
    }

    companion object {
        fun fromJson(v: Any?): Mutation {
            val o = v as Map<*, *>
            return Mutation(
                addTodo = o["addTodo"]?.let { Todo.fromJson(it) },
            )
        }
    }
}

data class NewTodo(
    val title: String,
    val tags: List<String>? = null,
    val priority: Long? = null,
    val meta: Any? = null,
) {
    fun toJson(): Map<String, Any?> = buildMap {
        put("title", title)
        if (tags != null) put("tags", tags)
        if (priority != null) put("priority", priority)
        if (meta != null) put("meta", meta)
    }

    companion object {
        fun fromJson(v: Any?): NewTodo {
            val o = v as Map<*, *>
            return NewTodo(
                title = (o["title"] as String),
                tags = o["tags"]?.let { (it as List<*>).map { (it as String) } },
                priority = o["priority"]?.let { (it as Number).toLong() },
                meta = o["meta"]?.let { it },
            )
        }
    }
}

data class Query(
    val todos: List<Todo>? = null,
    val todo: Todo? = null,
) {
    fun toJson(): Map<String, Any?> = buildMap {
        if (todos != null) put("todos", todos.map { it.toJson() })
        if (todo != null) put("todo", todo.toJson())
    }

    companion object {
        fun fromJson(v: Any?): Query {
            val o = v as Map<*, *>
            return Query(
                todos = o["todos"]?.let { (it as List<*>).map { Todo.fromJson(it) } },
                todo = o["todo"]?.let { Todo.fromJson(it) },
            )
        }
    }
}

enum class Status(val value: String) {
    OPEN("OPEN"),
    DONE("DONE"),
    INPROGRESS("IN_PROGRESS");

    fun toJson(): String = value

    companion object {
        fun fromJson(v: Any?): Status = entries.first { it.value == v }
    }
}

/** A thing to do. */
data class Todo(
    val id: String? = null,
    val title: String? = null,
    val done: Boolean? = null,
    val status: Status? = null,
    val tags: List<String>? = null,
    val score: Double? = null,
    val parent: Todo? = null,
    val owner: User? = null,
    val attachments: List<Any?>? = null,
) {
    fun toJson(): Map<String, Any?> = buildMap {
        if (id != null) put("id", id)
        if (title != null) put("title", title)
        if (done != null) put("done", done)
        if (status != null) put("status", status.toJson())
        if (tags != null) put("tags", tags)
        if (score != null) put("score", score)
        if (parent != null) put("parent", parent.toJson())
        if (owner != null) put("owner", owner.toJson())
        if (attachments != null) put("attachments", attachments)
    }

    companion object {
        fun fromJson(v: Any?): Todo {
            val o = v as Map<*, *>
            return Todo(
                id = o["id"]?.let { (it as String) },
                title = o["title"]?.let { (it as String) },
                done = o["done"]?.let { (it as Boolean) },
                status = o["status"]?.let { Status.fromJson(it) },
                tags = o["tags"]?.let { (it as List<*>).map { (it as String) } },
                score = o["score"]?.let { (it as Number).toDouble() },
                parent = o["parent"]?.let { Todo.fromJson(it) },
                owner = o["owner"]?.let { User.fromJson(it) },
                attachments = o["attachments"]?.let { (it as List<*>).map { it } },
            )
        }
    }
}

data class User(
    val id: String? = null,
    val name: String? = null,
) {
    fun toJson(): Map<String, Any?> = buildMap {
        if (id != null) put("id", id)
        if (name != null) put("name", name)
    }

    companion object {
        fun fromJson(v: Any?): User {
            val o = v as Map<*, *>
            return User(
                id = o["id"]?.let { (it as String) },
                name = o["name"]?.let { (it as String) },
            )
        }
    }
}

/** The errors a GraphQL response carried (each a decoded {"message", "path"?, "extensions"?}). */
class GraphQLException(val errors: List<Map<String, Any?>>, val data: Any?) :
    Exception(errors.joinToString("; ") { it["message"]?.toString() ?: "GraphQL error" })

/** Posts operations to [url]; [headers] are sent with every request. */
class GraphQLClient(
    private val url: String,
    private val headers: Map<String, String> = emptyMap(),
    private val http: HttpClient = defaultHttpClient(url),
    private val timeout: Duration = Duration.ofSeconds(30),
) {
    /** Run one operation; returns its decoded data, or throws [GraphQLException] when errors came back. */
    fun execute(query: String, variables: Map<String, Any?>? = null, operationName: String? = null): Any? {
        val payload = buildMap<String, Any?> {
            put("query", query)
            if (variables != null) put("variables", variables)
            if (operationName != null) put("operationName", operationName)
        }
        val builder = HttpRequest.newBuilder(URI.create(url))
            .timeout(timeout)
            .header("content-type", "application/json")
            .header("accept", "application/json")
        headers.forEach { (k, v) -> builder.header(k, v) }
        val response = http.send(
            builder.POST(HttpRequest.BodyPublishers.ofString(Json.stringify(payload))).build(),
            HttpResponse.BodyHandlers.ofString(),
        )
        val result = Json.parse(response.body()) as Map<*, *>
        val errors = (result["errors"] as? List<*>)?.map { e -> (e as Map<*, *>).entries.associate { (k, v) -> k.toString() to v } }
        if (!errors.isNullOrEmpty()) throw GraphQLException(errors, result["data"])
        return result["data"]
    }
}

/**
 * The default HTTP client: HTTP/2 over TLS (negotiated), HTTP/1.1 over plain http — the JDK's
 * cleartext HTTP/2 upgrade is refused by many servers (Deno's among them).
 */
internal fun defaultHttpClient(url: String): HttpClient =
    if (url.startsWith("https:", ignoreCase = true)) {
        HttpClient.newHttpClient()
    } else {
        HttpClient.newBuilder().version(HttpClient.Version.HTTP_1_1).build()
    }

/** A minimal JSON reader/writer: objects are Map<String, Any?>, arrays List<Any?>, numbers Long or Double. */
internal object Json {
    fun stringify(v: Any?): String = StringBuilder().also { write(it, v) }.toString()

    private fun write(sb: StringBuilder, v: Any?) {
        when (v) {
            null -> sb.append("null")
            is String -> quote(sb, v)
            is Boolean -> sb.append(v)
            is Double -> sb.append(if (v.isFinite()) v.toString() else "null")
            is Float -> write(sb, v.toDouble())
            is Number -> sb.append(v.toLong())
            is Map<*, *> -> {
                sb.append('{')
                var first = true
                for ((k, value) in v) {
                    if (!first) sb.append(',')
                    first = false
                    quote(sb, k.toString())
                    sb.append(':')
                    write(sb, value)
                }
                sb.append('}')
            }
            is Iterable<*> -> {
                sb.append('[')
                var first = true
                for (item in v) {
                    if (!first) sb.append(',')
                    first = false
                    write(sb, item)
                }
                sb.append(']')
            }
            else -> quote(sb, v.toString())
        }
    }

    private fun quote(sb: StringBuilder, s: String) {
        sb.append('"')
        for (c in s) {
            when (c) {
                '"' -> sb.append("\\\"")
                '\\' -> sb.append("\\\\")
                '\n' -> sb.append("\\n")
                '\r' -> sb.append("\\r")
                '\t' -> sb.append("\\t")
                else -> if (c < ' ') sb.append(String.format("\\u%04x", c.code)) else sb.append(c)
            }
        }
        sb.append('"')
    }

    fun parse(text: String): Any? {
        val p = Parser(text)
        val v = p.value()
        p.skip()
        require(p.i == text.length) { "trailing JSON" }
        return v
    }

    private class Parser(val s: String) {
        var i = 0

        fun skip() {
            while (i < s.length && s[i].isWhitespace()) i++
        }

        fun value(): Any? {
            skip()
            require(i < s.length) { "unexpected end of JSON" }
            return when (s[i]) {
                '{' -> obj()
                '[' -> arr()
                '"' -> str()
                't' -> word("true", true)
                'f' -> word("false", false)
                'n' -> word("null", null)
                else -> num()
            }
        }

        private fun word(w: String, v: Any?): Any? {
            require(s.startsWith(w, i)) { "bad JSON at $i" }
            i += w.length
            return v
        }

        private fun obj(): Map<String, Any?> {
            val out = LinkedHashMap<String, Any?>()
            i++
            skip()
            if (s[i] == '}') { i++; return out }
            while (true) {
                skip()
                val k = str()
                skip()
                require(s[i] == ':') { "bad JSON at $i" }
                i++
                out[k] = value()
                skip()
                if (s[i] == ',') { i++; continue }
                require(s[i] == '}') { "bad JSON at $i" }
                i++
                return out
            }
        }

        private fun arr(): List<Any?> {
            val out = ArrayList<Any?>()
            i++
            skip()
            if (s[i] == ']') { i++; return out }
            while (true) {
                out.add(value())
                skip()
                if (s[i] == ',') { i++; continue }
                require(s[i] == ']') { "bad JSON at $i" }
                i++
                return out
            }
        }

        private fun str(): String {
            require(s[i] == '"') { "bad JSON at $i" }
            i++
            val sb = StringBuilder()
            while (s[i] != '"') {
                val c = s[i++]
                if (c != '\\') { sb.append(c); continue }
                when (val e = s[i++]) {
                    'n' -> sb.append('\n')
                    't' -> sb.append('\t')
                    'r' -> sb.append('\r')
                    'b' -> sb.append('\b')
                    'f' -> sb.append('\u000c')
                    'u' -> { sb.append(s.substring(i, i + 4).toInt(16).toChar()); i += 4 }
                    else -> sb.append(e)
                }
            }
            i++
            return sb.toString()
        }

        private fun num(): Number {
            val start = i
            while (i < s.length && (s[i].isDigit() || s[i] in "+-.eE")) i++
            val t = s.substring(start, i)
            return if (t.any { it in ".eE" }) t.toDouble() else t.toLongOrNull() ?: t.toDouble()
        }
    }
}
